const fs = require('fs');
let c = fs.readFileSync('src/query/query-engine.ts', 'utf8');

// 1. Add 'EXISTS' to TCK_KEYWORDS
c = c.replace("'UNION','ALL','OPTIONAL',","'UNION','ALL','OPTIONAL','EXISTS',");
console.log('1. EXISTS keyword added');

// 2. Add WHERE filter for EXISTS subquery in _executeViaGraphEngine
// Find the _isPatternPredicate branch
const anchor = "if (_isPatternPredicate(plan.whereBody)) {";
let idx = c.indexOf(anchor);
if (idx < 0) { console.log('2a not found'); process.exit(1); }

// Find the end of this if block: "evalVal = isNegated ? false : true\n        } else {"
const blockEnd = c.indexOf('} else {', idx);
if (blockEnd < 0) { console.log('2b not found'); process.exit(1); }

// Insert EXISTS check
const existsBranch = `} else if (/^exists\\s*\\{/i.test(plan.whereBody.trim())) {
          // EXISTS { ... } 子查询：检查 allNodes 中该节点是否有出边
          const ebody = plan.whereBody.trim()
          const srcMatch = ebody.match(/\\((\\w+)/)
          let existsVal = false
          if (srcMatch && allNodes?.length) {
            const srcVar = srcMatch[1]
            const srcNode = ctx[srcVar]
            if (srcNode) {
              const srcProps = srcNode.props || srcNode
              const srcLabel = srcProps._label || ''
              for (const anode of allNodes) {
                if (anode._label !== srcLabel) continue
                let pm = true
                for (const k of Object.keys(srcProps)) {
                  if (k.startsWith('_') || k === 'name' || k === '__edges') continue
                  if (anode[k] !== srcProps[k]) { pm = false; break }
                }
                if (!pm) continue
                if (anode.__edges?.length) existsVal = true
                break
              }
            }
          }
          evalVal = existsVal
`;

c = c.substring(0, blockEnd) + existsBranch + c.substring(blockEnd);
console.log('2. EXISTS filter added');

// 3. Second location (WITH pipeline) — same logic
const anchor2 = "if (_isPatternPredicate(plan.whereBody)) {";
const idx2 = c.indexOf(anchor2, idx + 10); // second occurrence
if (idx2 < 0) { console.log('3a not found'); process.exit(1); }

const blockEnd2 = c.indexOf('} else {', idx2);
if (blockEnd2 < 0) { console.log('3b not found'); process.exit(1); }

const existsBranch2 = `} else if (/^exists\\s*\\{/i.test(plan.whereBody.trim())) {
              const ebody2 = plan.whereBody.trim()
              const srcMatch2 = ebody2.match(/\\((\\w+)/)
              let existsVal2 = false
              if (srcMatch2 && allNodes?.length) {
                const srcVar2 = srcMatch2[1]
                const srcNode2 = ctx[srcVar2]
                if (srcNode2) {
                  const srcProps2 = srcNode2.props || srcNode2
                  const srcLabel2 = srcProps2._label || ''
                  for (const anode of allNodes) {
                    if (anode._label !== srcLabel2) continue
                    let pm2 = true
                    for (const k of Object.keys(srcProps2)) {
                      if (k.startsWith('_') || k === 'name' || k === '__edges') continue
                      if (anode[k] !== srcProps2[k]) { pm2 = false; break }
                    }
                    if (!pm2) continue
                    if (anode.__edges?.length) existsVal2 = true
                    break
                  }
                }
              }
              evalVal = existsVal2
`;

c = c.substring(0, blockEnd2) + existsBranch2 + c.substring(blockEnd2);
console.log('3. Second EXISTS filter added');

fs.writeFileSync('src/query/query-engine.ts', c);
console.log('ALL DONE');
